#!/usr/bin/env python3
"""S301_MARG_VOUCHERS -- the Marg cleanup list becomes Marg vouchers Amir can key, and each one is
recorded as entered (S235 T7, D388), in the 09-Sep workbook's VOUCHER 1 - SHORT / VOUCHER 2 - EXCESS
layout.

stock_app.py (anchored edits over S299 75ffe861)
  1. the voucher engine before _amir_board: tables stock_voucher_line (a round's lines, frozen when
     made) and stock_voucher_entered (append-only); _voucher_pending = what the Marg cleanup list now
     needs minus what earlier rounds moved (a reversal included); _voucher_make (ISSUE and RECEIVE
     apart, sections together, at most six lines a batch -- setting stock.voucher_lines);
     _voucher_state; _voucher_workbook (the two voucher sheets);
  2. Amir's board carries `made`;
  3. the hub's step 6 counts what is not yet on a voucher and the vouchers entered;
  4. routes: POST /api/pad/vouchers/<cid>/make · POST /api/pad/vouchers/<cid>/entered ·
     GET /api/pad/vouchers/<cid>/<round>.xlsx.
stock_amir.html (over S299 3181d9de): card 2 -- what is waiting, "Make the Marg vouchers", every Marg
  voucher with its lines and "Entered in Marg" (Marg's own voucher number); the S299 lists kept
  underneath; opens at #vouchers from the hub.
stock_hub.html is shipped whole by the installer (over S299 d0bec54f): step 6 figures and the button.

    python3 -B patch_marg_vouchers_s301.py --app stock_app.py --amir stock_amir.html [--app-from M --amir-from M] [--dry-run]
"""
from __future__ import print_function
import argparse
import hashlib
import io
import shutil
import sys

VOUCHER_BLOCK = '# ---------------------------------------------------------------------------\n# S301 THE MARG VOUCHERS -- S235 T7 and D388, in the 09-Sep workbook\'s VOUCHER 1 - SHORT /\n# VOUCHER 2 - EXCESS layout. Everything on the Marg cleanup list (the confirmed swaps and the\n# lines the doctor has decided) becomes STOCK ISSUE and STOCK RECEIVE vouchers of at most six\n# lines -- one batch = one voucher in Marg -- and each batch is recorded as entered, with Marg\'s\n# own voucher number, so a round closes on the server and not only on paper.\n# A round, once made, is never edited. What changes afterwards (a new word, an answer taken\n# back) is only the DIFFERENCE between what the lines now need and what earlier rounds already\n# moved -- it goes on the next round, a reversal included. Keyed in order, Marg ends at the shelf.\n# ---------------------------------------------------------------------------\nVOUCHER_SCHEMA = """\nCREATE TABLE IF NOT EXISTS stock_voucher_line (\n  id         INTEGER PRIMARY KEY,         -- S301: one line of one Marg voucher, frozen when the round is made\n  count_id   INTEGER NOT NULL,            -- the ROOT count\n  round_no   INTEGER NOT NULL,\n  kind       TEXT NOT NULL,               -- ISSUE (Marg down) | RECEIVE (Marg up)\n  batch_no   INTEGER NOT NULL,            -- one batch = one voucher in Marg\n  batches_n  INTEGER NOT NULL,\n  line_no    INTEGER NOT NULL,\n  section    TEXT, family TEXT,\n  item       TEXT NOT NULL, packing TEXT, pack INTEGER,\n  marg_from  INTEGER NOT NULL,            -- units: the count-day Marg figure plus what earlier rounds moved\n  change     INTEGER NOT NULL,            -- units, signed\n  marg_to    INTEGER NOT NULL,\n  counted    INTEGER,                     -- the shelf on the count day\n  rate_p     INTEGER, value_p INTEGER,    -- paise; no value where Marg was below zero\n  reason     TEXT NOT NULL,\n  made_by    TEXT, made_at TEXT NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_svl_count ON stock_voucher_line(count_id, round_no, kind, batch_no);\nCREATE TABLE IF NOT EXISTS stock_voucher_entered (\n  id         INTEGER PRIMARY KEY,         -- S301: append-only; the newest row for a batch wins; an empty voucher_no clears it\n  count_id   INTEGER NOT NULL, round_no INTEGER NOT NULL, kind TEXT NOT NULL, batch_no INTEGER NOT NULL,\n  marg_voucher_no TEXT NOT NULL, entered_on TEXT, by_user TEXT, at TEXT NOT NULL\n);\n"""\nVOUCHER_KIND_TEXT = {"ISSUE": "STOCK ISSUE", "RECEIVE": "STOCK RECEIVE"}\nVOUCHER_SET_TEXT = {"ISSUE": "VOUCHER 1 - SHORT", "RECEIVE": "VOUCHER 2 - EXCESS"}\n_SECTION_ORDER = {"Orthotics": 0, "Medicines": 1, "Consumables": 2}\n\n\ndef _voucher_ensure(con):\n    con.executescript(VOUCHER_SCHEMA)\n\n\ndef _voucher_section(x):\n    if x.get("lane") == "consume" or x.get("consumable"):\n        return "Consumables", ""\n    if x.get("lane") == "ortho" or _is_orthotic(x["item"]):\n        g = _match_type_size(x["item"])[0]\n        label = " ".join(w if len(w) <= 2 else w.lower() for w in g.split())\n        return "Orthotics", label[:1].upper() + label[1:]\n    return "Medicines", ""\n\n\ndef _voucher_rate_p(x):\n    """Paise per unit at the count day\'s own rate (the rate the loss uses)."""\n    return _match_rate(dict(mrp_p=x.get("mrp_p_count_day", x.get("mrp_p")), diff=x.get("diff_count_day", x.get("diff"))))\n\n\ndef _voucher_frozen(con, root):\n    """item -> units already moved by rounds made so far (signed)."""\n    _voucher_ensure(con)\n    return {r[0]: int(r[1] or 0) for r in con.execute(\n        "SELECT item, SUM(change) FROM stock_voucher_line WHERE count_id=? GROUP BY item", (root,))}\n\n\ndef _voucher_pending(con, d):\n    """The lines the next round would carry: per item, what the Marg cleanup list now needs\n    minus what earlier rounds already moved. Ordered section, family, item."""\n    by = {x["item"]: x for x in d["differences"]}\n    need, why, why_word = {}, {}, {}\n    for v in _swap_vouchers(d):\n        need[v["item"]] = need.get(v["item"], 0) + int(v["change"])\n        why.setdefault(v["item"], []).append("swap confirmed -- " + v["note"])\n    for x in _word_vouchers(d):\n        need[x["item"]] = need.get(x["item"], 0) + int(x["change"])\n        w = x["word"]\n        txt = w["label"] + ((" -- " + w["note"]) if w.get("note") else "")\n        why.setdefault(x["item"], []).append(txt)\n        why_word.setdefault(x["item"], []).append(txt)\n    frozen = _voucher_frozen(con, d["count_id"])\n    out = []\n    for item in set(need) | set(frozen):\n        x = by.get(item)\n        if not x:\n            continue\n        ch = need.get(item, 0) - frozen.get(item, 0)\n        if not ch:\n            continue\n        sec, fam = _voucher_section(x)\n        m0 = int(x["marg"]) + frozen.get(item, 0)\n        rate = _voucher_rate_p(x)\n        reason = "; ".join(why.get(item) or [])\n        if frozen.get(item) and (not need.get(item) or (ch > 0) != (need.get(item, 0) > 0)):\n            reason = "corrects an earlier voucher" + ((" -- now: " + reason) if reason else " -- the answer or decision behind it was taken back")\n        elif frozen.get(item):\n            reason = "the rest of the line -- " + ("; ".join(why_word.get(item) or []) or reason)\n        out.append(dict(item=item, packing=x.get("packing") or "", pack=int(x.get("pack") or 1), section=sec, family=fam,\n                        kind=("ISSUE" if ch < 0 else "RECEIVE"), marg_from=m0, change=ch, marg_to=m0 + ch,\n                        counted=x.get("counted"), rate_p=rate,\n                        value_p=(None if rate is None or int(x["marg"]) < 0 else ch * rate), reason=reason))\n    out.sort(key=lambda r: (r["kind"], _SECTION_ORDER.get(r["section"], 9), r["family"], r["item"]))\n    return out\n\n\ndef _voucher_batch_size(con):\n    try:\n        return max(1, min(8, int(_stock_setting(con, "stock.voucher_lines", 6))))\n    except (TypeError, ValueError):\n        return 6\n\n\ndef _voucher_make(con, d, user):\n    """Freeze the pending lines as the next round: ISSUE and RECEIVE apart, sections kept\n    together, at most `stock.voucher_lines` (6) lines a batch. Returns (round_no, lines) or (None, 0)."""\n    _voucher_ensure(con)\n    con.execute("BEGIN IMMEDIATE")\n    try:\n        pend = _voucher_pending(con, d)\n        if not pend:\n            con.rollback()\n            return None, 0\n        root = d["count_id"]\n        rno = int((con.execute("SELECT MAX(round_no) FROM stock_voucher_line WHERE count_id=?", (root,)).fetchone() or [0])[0] or 0) + 1\n        size, at, n = _voucher_batch_size(con), now_iso(), 0\n        for kind in ("ISSUE", "RECEIVE"):\n            ls = [p for p in pend if p["kind"] == kind]\n            bn = (len(ls) + size - 1) // size\n            for i, p in enumerate(ls):\n                con.execute("INSERT INTO stock_voucher_line (count_id, round_no, kind, batch_no, batches_n, line_no, section, family, item, packing, pack, "\n                            "marg_from, change, marg_to, counted, rate_p, value_p, reason, made_by, made_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",\n                            (root, rno, kind, i // size + 1, bn, i + 1, p["section"], p["family"], p["item"], p["packing"], p["pack"],\n                             p["marg_from"], p["change"], p["marg_to"], p["counted"], p["rate_p"], p["value_p"], p["reason"][:500],\n                             (user or {}).get("user") or "", at))\n                n += 1\n        con.commit()\n        return rno, n\n    except Exception:\n        con.rollback()\n        raise\n\n\ndef _voucher_state(con, d):\n    """What Amir\'s board and the hub show: the pending lines, and every round made with its batches."""\n    _voucher_ensure(con)\n    root = d["count_id"]\n    pend = _voucher_pending(con, d)\n    size = _voucher_batch_size(con)\n    entered = {}\n    for r in con.execute("SELECT round_no, kind, batch_no, marg_voucher_no, entered_on, by_user, at FROM stock_voucher_entered "\n                         "WHERE count_id=? ORDER BY id", (root,)):\n        k = (r[0], r[1], r[2])\n        if not (r[3] or "").strip():\n            entered.pop(k, None)\n        else:\n            entered[k] = dict(no=r[3], on=r[4] or "", by=r[5] or "", at_text=_r_stamp(r[6]) + " IST")\n    rounds = {}\n    for r in con.execute("SELECT round_no, kind, batch_no, batches_n, line_no, section, family, item, packing, pack, marg_from, change, marg_to, "\n                         "counted, rate_p, value_p, reason, made_by, made_at FROM stock_voucher_line WHERE count_id=? "\n                         "ORDER BY round_no, kind, batch_no, line_no", (root,)):\n        rd = rounds.setdefault(r[0], dict(round_no=r[0], made_by=r[17] or "", made_text=_r_stamp(r[18]) + " IST", batches=[]))\n        if not rd["batches"] or (rd["batches"][-1]["kind"], rd["batches"][-1]["batch_no"]) != (r[1], r[2]):\n            rd["batches"].append(dict(kind=r[1], kind_text=VOUCHER_KIND_TEXT[r[1]], batch_no=r[2], batches_n=r[3], lines=[],\n                                      entered=entered.get((r[0], r[1], r[2]))))\n        b = rd["batches"][-1]\n        b["lines"].append(dict(line_no=r[4], section=r[5] or "", family=r[6] or "", item=r[7], packing=r[8] or "", pack=r[9] or 1,\n                               marg_from=r[10], change=r[11], marg_to=r[12], counted=r[13], rate_p=r[14], value_p=r[15], reason=r[16]))\n    out = []\n    for rno in sorted(rounds):\n        rd = rounds[rno]\n        for b in rd["batches"]:\n            b["n"] = len(b["lines"])\n            b["value_p"] = sum(l["value_p"] or 0 for l in b["lines"])\n            b["sections"] = sorted({l["section"] for l in b["lines"]}, key=lambda s: _SECTION_ORDER.get(s, 9))\n        rd["entered"] = sum(1 for b in rd["batches"] if b["entered"])\n        rd["total"] = len(rd["batches"])\n        rd["closed"] = rd["entered"] == rd["total"]\n        rd["xlsx"] = "/finance/stock/api/pad/vouchers/%d/%d.xlsx" % (root, rno)\n        out.append(rd)\n    n_issue = sum(1 for p in pend if p["kind"] == "ISSUE")\n    n_recv = len(pend) - n_issue\n    return dict(pending=pend, pending_issue=n_issue, pending_receive=n_recv,\n                would_make=((n_issue + size - 1) // size) + ((n_recv + size - 1) // size), batch_size=size,\n                rounds=out, batches_total=sum(r["total"] for r in out), batches_entered=sum(r["entered"] for r in out),\n                all_entered=bool(out) and all(r["closed"] for r in out))\n\n\ndef _voucher_workbook(con, d, rno):\n    """One round as the 09-Sep workbook\'s two voucher sheets."""\n    import padwriter                                          # noqa: PLC0415\n    st = _voucher_state(con, d)\n    rd = [r for r in st["rounds"] if r["round_no"] == rno]\n    if not rd:\n        return None\n    rd = rd[0]\n    rs = lambda p_: None if p_ is None else round(p_ / 100.0, 2)          # noqa: E731\n    sheets = []\n    for kind in ("ISSUE", "RECEIVE"):\n        bs = [b for b in rd["batches"] if b["kind"] == kind]\n        if not bs:\n            continue\n        sh = padwriter.Sheet()\n        short = kind == "ISSUE"\n        sh.text(1, 0, ("VOUCHER 1 · STOCK SHORT — TO BE REDUCED IN MARG" if short else "VOUCHER 2 · STOCK EXCESS — TO BE ADDED IN MARG"), padwriter.TITLE)\n        sh.text(2, 0, "Sanjeevni Medicos, Bareilly · stock count #%d of %s · round %d, made %s by %s · one round is never overwritten; a change goes on the next round."\n                % (d["count_id"], d["day"], rno, rd["made_text"], rd["made_by"] or "-"), padwriter.NOTE)\n        sh.text(3, 0, ("Every product where the shelf holds LESS than Marg says — including the item that left the shelf in a confirmed swap. Marg must be brought DOWN, by CORRECTION, with a STOCK ISSUE voucher."\n                       if short else "Every product where the shelf holds MORE than Marg says — including the item that was billed in a confirmed swap, and Marg balances below zero. Marg must be brought UP, by CORRECTION, with a STOCK RECEIVE voucher. This is not income."), padwriter.NOTE)\n        sh.text(4, 0, "MARG PRINTS ONLY SIX TO EIGHT LINES ON ONE VOUCHER. So this correction is broken into %d SEPARATE MARG VOUCHER%s of at most %d items each. Enter one batch as one voucher in Marg, print it, check it against the batch here, then move to the next."\n                % (len(bs), "" if len(bs) == 1 else "S", st["batch_size"]), padwriter.NOTE)\n        r = 6\n        for label, val in (("Voucher set no.", "SC%d-R%d-%s" % (d["count_id"], rno, "OUT" if short else "IN")),\n                           ("Voucher type", VOUCHER_KIND_TEXT[kind] + (" — reduce in Marg" if short else " — add in Marg")),\n                           ("Marg vouchers in this set", "%d  (at most %d items each)" % (len(bs), st["batch_size"])),\n                           ("Entered and corrected in Marg by (Amir)", ""), ("All batches printed and checked by", ""),\n                           ("Checked by (Dr Manoj Agarwal)", ""), ("Date closed", "")):\n            sh.text(r, 0, label, padwriter.BOLD); sh.text(r, 2, val, padwriter.INPUT if not val else padwriter.BOX); r += 1\n        r += 1\n        sh.text(r, 0, "BATCH SUMMARY — tick each batch off as it is entered and printed", padwriter.SUBHEAD); r += 1\n        for i, h in enumerate(("Batch", "Items", "Value of the batch (Rs)", "Marg voucher no.", "Printed & checked (yes)", "Entered on", "Initials")):\n            sh.text(r, i, h, padwriter.HEADER)\n        r += 1\n        for b in bs:\n            e = b["entered"] or {}\n            sh.text(r, 0, "Batch %d of %d" % (b["batch_no"], b["batches_n"]), padwriter.BOX); sh.num(r, 1, b["n"], padwriter.BOX)\n            sh.num(r, 2, rs(b["value_p"]), padwriter.BOX)\n            sh.text(r, 3, e.get("no", ""), padwriter.BOX if e else padwriter.INPUT); sh.text(r, 4, "yes" if e else "", padwriter.BOX if e else padwriter.INPUT)\n            sh.text(r, 5, e.get("on", ""), padwriter.BOX if e else padwriter.INPUT); sh.text(r, 6, "", padwriter.INPUT)\n            r += 1\n        sh.text(r, 0, "TOTAL", padwriter.BOLDBOX); sh.num(r, 1, sum(b["n"] for b in bs), padwriter.BOLDBOX); sh.num(r, 2, rs(sum(b["value_p"] for b in bs)), padwriter.BOLDBOX)\n        r += 2\n        sh.text(r, 0, "HOW TO USE THIS SHEET", padwriter.SUBHEAD); r += 1\n        for t in ("•  Yellow cells are the ones to fill in. Everything else is already worked out — do not retype it.",\n                  "•  CORRECTION is what must be %s the Marg quantity. MARG AFTER is what Marg must read once the voucher is entered." % ("taken off" if short else "added to"),\n                  "•  ONE BATCH = ONE VOUCHER IN MARG. Never mix two batches into one Marg voucher, and never split a batch across two.",\n                  "•  After entering a batch, print that Marg voucher and read it against the batch below, line by line. Then record its Marg voucher number on Amir\'s board (Stock Check → Amir\'s board → the vouchers) — that is what closes it on the server.",\n                  "•  A confirmed swap is always two lines: STOCK ISSUE on the item that left the shelf (this sheet or VOUCHER 1) and STOCK RECEIVE on the item that was billed (VOUCHER 2)."):\n            sh.text(r, 0, t, padwriter.NORMAL); r += 1\n        r += 1\n        heads = ("Family", "Item", "Qty in Marg", "Counted %s" % (d["day"] or ""), "CORRECTION", "Marg after", "Rate used (Rs)", "Value of the correction (Rs)",\n                 "Reason / what happened", "Corrected in Marg on", "Initials")\n        for i, h in enumerate(heads):\n            sh.text(r, i, h, padwriter.HEADER)\n        head_row = r\n        r += 1\n        for b in bs:\n            sh.text(r, 0, "MARG VOUCHER  %d  of  %d   —   enter these %d items as ONE voucher in Marg   ·   %s   ·   %s"\n                    % (b["batch_no"], b["batches_n"], b["n"], " + ".join(s.upper() for s in b["sections"]), VOUCHER_KIND_TEXT[kind]), padwriter.GROUPYELLOW)\n            r += 1\n            for l in b["lines"]:\n                sh.text(r, 0, l["family"] or l["section"], padwriter.BOX); sh.text(r, 1, l["item"], padwriter.BOX)\n                sh.num(r, 2, l["marg_from"], padwriter.BOX); sh.num(r, 3, l["counted"], padwriter.BOX)\n                sh.num(r, 4, l["change"], padwriter.BOLDBOX); sh.num(r, 5, l["marg_to"], padwriter.BOX)\n                sh.num(r, 6, rs(l["rate_p"]), padwriter.BOX)\n                if l["value_p"] is None:\n                    sh.text(r, 7, "no value — Marg was below zero" if l["rate_p"] is not None else "not priced", padwriter.BOX)\n                else:\n                    sh.num(r, 7, rs(l["value_p"]), padwriter.BOX)\n                sh.text(r, 8, l["reason"], padwriter.BOX); sh.text(r, 9, (b["entered"] or {}).get("on", ""), padwriter.BOX if b["entered"] else padwriter.INPUT)\n                sh.text(r, 10, "", padwriter.INPUT)\n                r += 1\n            sh.text(r, 0, "Batch %d — %d items, value" % (b["batch_no"], b["n"]), padwriter.BOLD)\n            sh.num(r, 4, sum(l["change"] for l in b["lines"]), padwriter.BOLDBOX); sh.num(r, 7, rs(b["value_p"]), padwriter.BOLDBOX)\n            r += 2\n        sh.text(r, 0, "SIGN-OFF — only when every batch above is entered, printed and checked", padwriter.SUBHEAD); r += 1\n        for t in ("Counted by", "Entered and corrected in Marg by (Amir)", "All batches printed and checked by", "Checked by (Dr Manoj Agarwal)", "Date closed"):\n            sh.text(r, 0, t, padwriter.BOLD); sh.text(r, 2, "", padwriter.INPUT); r += 1\n        sh.widths = {0: 22, 1: 34, 2: 11, 3: 12, 4: 12, 5: 11, 6: 11, 7: 14, 8: 52, 9: 16, 10: 9}\n        sh.print_title_rows = (head_row, head_row)\n        sheets.append((VOUCHER_SET_TEXT[kind], sh))\n    return padwriter.workbook_bytes_multi(sheets)\n'

ROUTES_BLOCK = '@bp.route("/api/pad/vouchers/<int:cid>/make", methods=["POST"])\ndef api_pad_vouchers_make(cid):\n    """S301: freeze what is waiting as the next round of Marg vouchers. Idempotent in effect: a\n    second press finds nothing waiting."""\n    u, err = _require("checker", "maker", "viewer")\n    if err:\n        return err\n    con = _db()\n    ensure_schema(con)\n    _pad_ensure(con)\n    d = _pad_report_data(con, cid)\n    if d is None:\n        return jsonify(ok=False, error="not_found", message="No count #%d." % cid), 404\n    if con.in_transaction:\n        con.commit()\n    rno, n = _voucher_make(con, d, u)\n    if not rno:\n        return jsonify(ok=True, round_no=None, lines=0, message="Nothing is waiting to go on a voucher.")\n    st = _voucher_state(con, d)\n    rd = [r for r in st["rounds"] if r["round_no"] == rno][0]\n    return jsonify(ok=True, round_no=rno, lines=n, batches=rd["total"],\n                   message="Round %d made: %d line%s on %d Marg voucher%s. Download the Excel, enter each voucher in Marg, then record its number here."\n                   % (rno, n, "" if n == 1 else "s", rd["total"], "" if rd["total"] == 1 else "s"))\n\n\n@bp.route("/api/pad/vouchers/<int:cid>/entered", methods=["POST"])\ndef api_pad_vouchers_entered(cid):\n    """S301: one Marg voucher entered -- Marg\'s own voucher number (and the date), or clear=true to undo.\n    Append-only; the voucher number also lands in stock_voucher (S221), the finding\'s record."""\n    u, err = _require("checker", "maker", "viewer")\n    if err:\n        return err\n    b = request.get_json(silent=True) or {}\n    try:\n        rno, bno = int(b.get("round")), int(b.get("batch"))\n    except (TypeError, ValueError):\n        return jsonify(ok=False, error="bad_request", message="round and batch are needed."), 400\n    kind = str(b.get("kind") or "").upper()\n    clear = bool(b.get("clear"))\n    no = str(b.get("marg_voucher_no") or "").strip()[:40]\n    on = str(b.get("entered_on") or "").strip()[:20] or dt.date.today().strftime("%d-%m-%Y")\n    if kind not in VOUCHER_KIND_TEXT or (not clear and not no):\n        return jsonify(ok=False, error="bad_request", message="Write Marg\'s voucher number first."), 400\n    con = _db()\n    ensure_schema(con)\n    _pad_ensure(con)\n    _voucher_ensure(con)\n    _root, fam, R = _pad_family(con, cid)\n    if R is None:\n        return jsonify(ok=False, error="not_found", message="No count #%d." % cid), 404\n    r = con.execute("SELECT batches_n, COUNT(*) FROM stock_voucher_line WHERE count_id=? AND round_no=? AND kind=? AND batch_no=?",\n                    (_root, rno, kind, bno)).fetchone()\n    if not r or not r[1]:\n        return jsonify(ok=False, error="no_such_voucher", message="No such voucher in round %d." % rno), 400\n    at, who = now_iso(), (u or {}).get("user") or ""\n    con.execute("INSERT INTO stock_voucher_entered (count_id, round_no, kind, batch_no, marg_voucher_no, entered_on, by_user, at) VALUES (?,?,?,?,?,?,?,?)",\n                (_root, rno, kind, bno, "" if clear else no, None if clear else on, who, at))\n    if not clear:\n        try:\n            _f_ensure(con)\n            con.execute("INSERT INTO stock_voucher (count_id, voucher_no, voucher_date, note, scan_ref, recorded_by, recorded_at) VALUES (?,?,?,?,?,?,?)",\n                        (_root, no, on, "S301 round %d · %s · Marg voucher %d of %d" % (rno, VOUCHER_KIND_TEXT[kind], bno, r[0]), None, who, at))\n        except Exception:                                     # noqa: BLE001 -- the S301 record above is the one that counts\n            pass\n    con.commit()\n    return jsonify(ok=True, message=("Taken back." if clear else "Recorded: %s %d of %d entered in Marg as voucher %s." % (VOUCHER_KIND_TEXT[kind], bno, r[0], no)))\n\n\n@bp.route("/api/pad/vouchers/<int:cid>/<int:rno>.xlsx")\ndef api_pad_vouchers_xlsx(cid, rno):\n    """S301: one round of Marg vouchers, as the 09-Sep workbook\'s VOUCHER 1 - SHORT and VOUCHER 2 - EXCESS."""\n    u, err = _require("checker", "maker", "viewer")\n    if err:\n        return err\n    con = _db()\n    ensure_schema(con)\n    _pad_ensure(con)\n    d = _pad_report_data(con, cid)\n    if d is None:\n        return jsonify(ok=False, error="not_found", message="No count #%d." % cid), 404\n    data = _voucher_workbook(con, d, rno)\n    if data is None:\n        return jsonify(ok=False, error="not_found", message="No round %d on count #%d." % (rno, cid)), 404\n    return _xlsx_response(data, "STOCK_COUNT_%s_MARG_VOUCHERS_ROUND_%d.xlsx" % (d["day"] or "", rno))\n'

